package br.com.multisaude.agenda;

import java.time.OffsetDateTime; import java.util.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import br.com.multisaude.identidade.IdentityModels.Session; import br.com.multisaude.shared.TenantTransactions; import static br.com.multisaude.agenda.AgendaModels.*;

@RestController @RequestMapping("/api/v1") public class AgendaController { private final AgendaRepository repo; private final TenantTransactions tx; private final AppointmentService appointments; private final AgendaAccess access; public AgendaController(AgendaRepository repo,TenantTransactions tx,AppointmentService appointments,AgendaAccess access){this.repo=repo;this.tx=tx;this.appointments=appointments;this.access=access;}
 @GetMapping("/agendamento-motivos") @PreAuthorize("hasAnyAuthority('agenda:ler','agenda:ler_proprios')") public List<MotiveView> motives(@AuthenticationPrincipal Session s){return tx.inTenant(s.identity().tenantId(),repo::motives);}
 @GetMapping("/agendamentos/{id}/historico") @PreAuthorize("hasAnyAuthority('agenda:ler','agenda:ler_proprios')") public List<HistoryView> history(@AuthenticationPrincipal Session s,@PathVariable UUID id){return tx.inTenant(s.identity().tenantId(),()->{var scope=access.scope(s);if(!scope.all()&&!scope.canSee(repo.appointmentProfessional(id).orElse(null)))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Agendamento não encontrado.");return repo.history(id);});}
 @PostMapping("/agendamentos/{id}/status") @PreAuthorize("hasAnyAuthority('agenda:editar','agenda:atender')") public AppointmentView status(@AuthenticationPrincipal Session s,@PathVariable UUID id,@Valid @RequestBody StatusRequest x){return appointments.updateStatus(s,id,x);}
 @PostMapping("/agendamentos/{id}/cancelar") @PreAuthorize("hasAuthority('agenda:cancelar')") public AppointmentView cancel(@AuthenticationPrincipal Session s,@PathVariable UUID id,@Valid @RequestBody CancelRequest x){return appointments.cancel(s,id,x);}
 @PostMapping("/agendamentos/{id}/remarcar") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAuthority('agenda:remarcar')") public AppointmentView reschedule(@AuthenticationPrincipal Session s,@PathVariable UUID id,@Valid @RequestBody RescheduleRequest x){return appointments.reschedule(s,id,x);}
 @GetMapping("/procedimentos") @PreAuthorize("hasAnyAuthority('agenda:ler','agenda:ler_proprios')") public List<ProcedureView> procedures(@AuthenticationPrincipal Session s){return tx.inTenant(s.identity().tenantId(),repo::procedures);}
 @PostMapping("/procedimentos") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAuthority('agenda:criar')") public ProcedureView procedure(@AuthenticationPrincipal Session s,@Valid @RequestBody CreateProcedureRequest x){return tx.inTenant(s.identity().tenantId(),()->repo.createProcedure(x,s.identity().tenantId()));}
 @GetMapping("/agendamentos") @PreAuthorize("hasAnyAuthority('agenda:ler','agenda:ler_proprios')") public List<AppointmentView> appointments(@AuthenticationPrincipal Session s,@RequestParam UUID profissionalId,@RequestParam OffsetDateTime de,@RequestParam OffsetDateTime ate){if(!ate.isAfter(de))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Intervalo inválido.");return tx.inTenant(s.identity().tenantId(),()->{access.scope(s).requireCanSee(profissionalId);return repo.appointments(profissionalId,de,ate);});}
 @PostMapping("/agendamentos") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAuthority('agenda:criar')") public AppointmentView appointment(@AuthenticationPrincipal Session s,@Valid @RequestBody CreateAppointmentRequest x){return appointments.create(s,x);}
}
